export const c11Phy3HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n\n  <!-- QUICK GLOSSARY & BASIC DEFINITIONS -->\n  <div style=\"background: rgba(255, 138, 101, 0.05); border: 1.5px solid #FF8A65; border-radius: 12px; padding: 18px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #FF8A65; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">📖 Quick Glossary & Basic Definitions</h2>\n    <p class=\"text-center\" style=\"color: #FF8A65; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Essential Core Terms for Unit II: Motion in a Plane</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF8A65; border-radius: 6px;\">\n        <b style='color: #FF8A65; display: block; margin-bottom: 4px;'>1. Scalar Quantity:</b>\n        <span style=\"color: #FFFFFF;\">Physical quantity possessing magnitude only, obeying ordinary rules of algebra (e.g. Mass, Speed, Work).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF8A65; border-radius: 6px;\">\n        <b style='color: #FF8A65; display: block; margin-bottom: 4px;'>2. Vector Quantity:</b>\n        <span style=\"color: #FFFFFF;\">Physical quantity possessing both magnitude and direction, obeying vector addition rules (e.g. Displacement, Velocity, Force).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF8A65; border-radius: 6px;\">\n        <b style='color: #FF8A65; display: block; margin-bottom: 4px;'>3. Unit Vector (Â):</b>\n        <span style=\"color: #FFFFFF;\">A vector of unit magnitude indicating direction: Â = A⃗ / |A⃗|. Cartesians: î, ĵ, k̂.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF8A65; border-radius: 6px;\">\n        <b style='color: #FF8A65; display: block; margin-bottom: 4px;'>4. Dot (Scalar) Product:</b>\n        <span style=\"color: #FFFFFF;\">A⃗ · B⃗ = |A⃗||B⃗| cosθ. Produces a scalar. Maximum when parallel (θ=0°), zero when perpendicular (θ=90°).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF8A65; border-radius: 6px;\">\n        <b style='color: #FF8A65; display: block; margin-bottom: 4px;'>5. Cross (Vector) Product:</b>\n        <span style=\"color: #FFFFFF;\">A⃗ × B⃗ = |A⃗||B⃗| sinθ n̂. Produces a vector perpendicular to plane containing A⃗ and B⃗ via right-hand rule.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF8A65; border-radius: 6px;\">\n        <b style='color: #FF8A65; display: block; margin-bottom: 4px;'>6. Projectile Motion:</b>\n        <span style=\"color: #FFFFFF;\">Two-dimensional curved parabolic motion under constant vertical downward gravity acceleration (a_x = 0, a_y = -g).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF8A65; border-radius: 6px;\">\n        <b style='color: #FF8A65; display: block; margin-bottom: 4px;'>7. Uniform Circular Motion:</b>\n        <span style=\"color: #FFFFFF;\">Motion along a circular path at constant speed, possessing radially inward centripetal acceleration a_c = v²/r = ω²r.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF8A65; border-radius: 6px;\">\n        <b style='color: #FF8A65; display: block; margin-bottom: 4px;'>8. Relative Velocity in 2D:</b>\n        <span style=\"color: #FFFFFF;\">Velocity of object A relative to object B in 2D space: v⃗_AB = v⃗_A - v⃗_B.</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 1: SCALAR & VECTOR QUANTITIES -->\n  <h2 style=\"color: #FF8A65; border-bottom: 2px solid #FF8A65; padding-bottom: 6px; margin-top: 25px;\">1. Scalar and Vector Quantities, Position and Displacement Vectors</h2>\n\n  <p>Two-dimensional kinematics analyzes motion occurring within a plane defined by two orthogonal spatial axes $X$ and $Y$. Physical quantities in two dimensions are broadly divided into scalars and vectors.</p>\n\n  <p>A <b>Scalar Quantity</b> is completely specified by a single real number representing its magnitude alongside its appropriate physical unit (e.g. Mass, Temperature, Distance, Energy). Scalars add algebraically according to ordinary rules of arithmetic.</p>\n\n  <p>A <b>Vector Quantity</b> possesses both a magnitude and a definite spatial direction, obeying vector addition rules like the Triangle and Parallelogram laws (e.g. Position $mathbf{r}$, Velocity $mathbf{v}$, Acceleration $mathbf{a}$, Force $mathbf{F}$).</p>\n\n  <h3 style=\"color: #FF8A65; margin-top: 18px;\">(i) Position and Displacement Vectors in 2D</h3>\n  <p>The position of a particle at point $P(x,y)$ relative to origin $O$ is specified by the <b>Position Vector</b> $mathbf{r} = x hat{i} + y hat{j}$. When the particle moves to $P'(x',y')$, its <b>Displacement Vector</b> is $Delta mathbf{r} = mathbf{r}' - mathbf{r} = (x'-x)hat{i} + (y'-y)hat{j}$.</p>\n\n  <!-- SECTION 2: VECTOR ADDITION & COMPONENTS -->\n  <h2 style=\"color: #FF8A65; border-bottom: 2px solid #FF8A65; padding-bottom: 6px; margin-top: 30px;\">2. Addition and Subtraction of Vectors, Unit Vectors &amp; Rectangular Components</h2>\n\n  <p>Vectors cannot be added algebraically. According to the <b>Parallelogram Law of Vector Addition</b>, if two vectors $mathbf{A}$ and $mathbf{B}$ inclined at angle $\theta$ are represented by adjacent sides of a parallelogram, their resultant $mathbf{R} = mathbf{A} + mathbf{B}$ is represented by the diagonal passing through their common tail:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 138, 101, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>Resultant R = √(A<sup>2</sup> + B<sup>2</sup> + 2 A B cos θ) &nbsp;|&nbsp; Direction tan α = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">B sin θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">A + B cos θ</span>\n  </span></b></div>\n\n  <p>A <b>Unit Vector ($hat{A} = \frac{mathbf{A}}{|mathbf{A}|}$)</b> is a dimensionless vector of unit magnitude indicating pure direction. Resolving a vector $mathbf{A}$ into rectangular components yields $mathbf{A}_x = A cos\theta hat{i}$ and $mathbf{A}_y = A sin\theta hat{j}$.</p>\n\n  <!-- SECTION 3: SCALAR AND VECTOR PRODUCTS -->\n  <h2 style=\"color: #FF8A65; border-bottom: 2px solid #FF8A65; padding-bottom: 6px; margin-top: 30px;\">3. Scalar (Dot) and Vector (Cross) Product of Vectors</h2>\n\n  <p>The <b>Scalar (Dot) Product</b> of two vectors $mathbf{A}$ and $mathbf{B}$ is defined as $mathbf{A} cdot mathbf{B} = |mathbf{A}| |mathbf{B}| cos\theta = A_x B_x + A_y B_y + A_z B_z$. It is maximum when vectors are parallel ($\theta = 0circ$) and vanishes when vectors are orthogonal ($\theta = 90circ$).</p>\n\n  <p>The <b>Vector (Cross) Product</b> is defined as $mathbf{A} \times mathbf{B} = |mathbf{A}| |mathbf{B}| sin\theta hat{n}$, where $hat{n}$ is a unit vector perpendicular to the plane containing $mathbf{A}$ and $mathbf{B}$ given by the Right-Hand Thumb Rule.</p>\n\n  <!-- SECTION 4: PROJECTILE MOTION -->\n  <h2 style=\"color: #FF8A65; border-bottom: 2px solid #FF8A65; padding-bottom: 6px; margin-top: 30px;\">4. Projectile Motion</h2>\n\n  <p>When an object is thrown into space with an initial velocity $u$ at an angle $\theta$ to the horizontal and allowed to move under gravity alone, it executes <b>Projectile Motion</b> along a parabolic trajectory.</p>\n\n  <p>The horizontal motion has zero acceleration ($a_x = 0, u_x = u cos\theta = \text{Constant}$), while vertical motion experiences constant downward acceleration ($a_y = -g, u_y = u sin\theta$).</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 138, 101, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>Time of Flight T = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 u sin θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span> &nbsp;|&nbsp; Max Height H = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">u<sup>2</sup> sin<sup>2</sup> θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2 g</span>\n  </span> &nbsp;|&nbsp; Range R = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">u<sup>2</sup> sin 2θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span></b></div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF8A65; border-radius: 16px; padding: 18px; margin: 26px 0; box-shadow: 0 10px 30px rgba(255, 138, 101, 0.25);\">\n    <div style=\"color: #FF8A65; font-weight: bold; font-size: 17.5px; margin-bottom: 14px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Parabolic Projectile Motion Trajectory & Velocity Vectors\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 840 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <g transform=\"translate(15, 20)\">\n    <text x=\"390\" y=\"30\" text-anchor=\"middle\" fill=\"#FF8A65\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">Parabolic Projectile Trajectory y(x) &amp; Velocity Vectors</text>\n\n    <!-- Axes -->\n    <line x1=\"50\" y1=\"360\" x2=\"740\" y2=\"360\" stroke=\"#475569\" stroke-width=\"2.5\"/>\n    <line x1=\"60\" y1=\"360\" x2=\"60\" y2=\"50\" stroke=\"#475569\" stroke-width=\"2.5\"/>\n    <text x=\"745\" y=\"365\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13.5\">Horizontal Range R</text>\n    <text x=\"50\" y=\"45\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13.5\">Height y</text>\n\n    <!-- Parabola -->\n    <path d=\"M 60 360 Q 390 40 720 360\" fill=\"none\" stroke=\"#FF8A65\" stroke-width=\"3.5\"/>\n\n    <!-- Launch Velocity -->\n    <line x1=\"60\" y1=\"360\" x2=\"160\" y2=\"240\" stroke=\"#76FF03\" stroke-width=\"3\"/>\n    <text x=\"120\" y=\"230\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">u → (Angle θ)</text>\n\n    <!-- Peak H_max -->\n    <line x1=\"390\" y1=\"140\" x2=\"390\" y2=\"360\" stroke=\"#00E5FF\" stroke-dasharray=\"4,4\" stroke-width=\"2\"/>\n    <circle cx=\"390\" cy=\"140\" r=\"7\" fill=\"#00E5FF\"/>\n    <text x=\"390\" y=\"115\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Peak H_max (v_y = 0)</text>\n\n    <text x=\"390\" y=\"410\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Trajectory Equation: y = x tanθ - [ g / (2 u² cos²θ) ] x²</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Parabolic path y(x) showing initial velocity u at angle θ, peak height H_max, time of flight T, and range R.\n    </div>\n  </div>\n\n  <!-- SECTION 5: UNIFORM CIRCULAR MOTION -->\n  <h2 style=\"color: #FF8A65; border-bottom: 2px solid #FF8A65; padding-bottom: 6px; margin-top: 30px;\">5. Uniform Circular Motion</h2>\n\n  <p>When a particle moves along a circular path of radius $r$ at a constant linear speed $v$, it undergoes <b>Uniform Circular Motion</b>. Although speed is constant, the velocity vector continuously changes direction, giving rise to a centripetal acceleration directed towards the center of the circle:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 138, 101, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>a<sub>c</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r</span>\n  </span> = ω<sup>2</sup> r &nbsp;|&nbsp; Angular Velocity ω = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">dθ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">dt</span>\n  </span> = 2π ν</b></div>\n\n  <!-- QUICK REVISION CHEAT SHEET -->\n  <div style=\"background: rgba(255, 138, 101, 0.05); border: 1.5px solid #FF8A65; border-radius: 12px; padding: 18px; margin-top: 35px; margin-bottom: 15px;\">\n    <h2 class=\"text-center\" style=\"color: #FF8A65; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">⚡ Quick Revision Cheat Sheet</h2>\n    <p class=\"text-center\" style=\"color: #FF8A65; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Summary Formulae for Unit II: Motion in a Plane</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px; font-size: 14.5px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF8A65; border-radius: 6px;\">\n        <b style='color: #FF8A65; display: block; margin-bottom: 4px;'>• Vector Products:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.65; display: block;\">A⃗ · B⃗ = A B cosθ<br>|A⃗ × B⃗| = A B sinθ</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF8A65; border-radius: 6px;\">\n        <b style='color: #FF8A65; display: block; margin-bottom: 4px;'>• Projectile Equations:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.65; display: block;\">T = 2u sinθ / g<br>H = u² sin²θ / (2g)<br>R = u² sin2θ / g (Max at θ=45°)</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF8A65; border-radius: 6px;\">\n        <b style='color: #FF8A65; display: block; margin-bottom: 4px;'>• Circular Motion:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.65; display: block;\">a_c = v²/r = ω²r<br>v = ω r &nbsp;|&nbsp; T = 2π / ω</span>\n      </div>\n    </div>\n  </div>\n\n</div>\n";

export const c11Phy3HtmlSolutions = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.7; font-size: 16px;\">\n  \n  <div style=\"text-align: center; margin-bottom: 25px; border-bottom: 2px solid #FF8A65; padding-bottom: 10px;\">\n    <h2 style=\"color: #FF8A65; margin: 0; font-size: 22px; font-weight: bold; text-align: center !important;\">NCERT & Master Solutions Guide</h2>\n    <p style=\"color: #B0BEC5; margin: 5px 0 0 0; font-size: 15px; text-align: center !important;\">Unit III: Laws of Motion — 100 Master Practice Questions (Theoretical & Numerical)</p>\n  </div>\n<h3 style=\"color: #FF8A65; border-left: 4px solid #FF8A65; padding-left: 10px; margin-top: 25px;\">Part A: Multiple Choice Questions (Q1 - Q25)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q1: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Newton's First Law of Motion defines which fundamental physical quantity?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Energy</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Work</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Force</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Power</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">c) Force</span></b><br>Newton's First Law provides the qualitative definition of Force as an external agency that alters state of rest or uniform motion.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q2: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Which property of a body measures its quantitative inertia?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Velocity</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Volume</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Mass</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Weight</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">c) Mass</span></b><br>Mass is the quantitative measure of inertia; larger mass implies greater resistance to change in motion.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q3: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">If net external force acting on a body is zero, its acceleration is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Zero</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Infinite</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Constant non-zero</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Equal to g</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">a) Zero</span></b><br>From F = m a, if F = 0, acceleration a = 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q4: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 5 kg block is acted upon by a net force of 20 N. Its acceleration is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 2 m s<sup>-2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 4 m s<sup>-2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 5 m s<sup>-2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 100 m s<sup>-2</sup></div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">b) 4 m s<sup>-2</sup></span></b><br>a = F / m = 20 / 5 = 4 m s<sup>-2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q5: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The SI unit of Impulse is identical to the SI unit of:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Force</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Energy</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Linear Momentum</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Power</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">c) Linear Momentum</span></b><br>Impulse J = Δp (change in momentum), so its unit is N s or kg m s<sup>-1</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q6: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Action and reaction forces described in Newton's Third Law:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Act on the same body</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Act on two different bodies simultaneously</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Act at different times</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Cancel each other completely on one body</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">b) Act on two different bodies simultaneously</span></b><br>Action and reaction act on different bodies (F<sub>12</sub> = -F<sub>21</sub>), so they never cancel out on a single object.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q7: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A bullet of mass 0.02 kg is fired with velocity 500 m s<sup>-1</sup> from a rifle of mass 4 kg. The recoil velocity of rifle is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) -2.5 m s<sup>-1</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) -5.0 m s<sup>-1</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) -10 m s<sup>-1</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) -0.5 m s<sup>-1</sup></div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">a) -2.5 m s<sup>-1</sup></span></b><br>v<sub>recoil</sub> = -(m v)/M = -(0.02 × 500)/4 = -10 / 4 = -2.5 m s<sup>-1</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q8: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Static friction f<sub>s</sub> is a:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Constant force</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Self-adjusting force</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Zero force always</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Force greater than limiting friction</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">b) Self-adjusting force</span></b><br>Static friction automatically adjusts its magnitude equal to applied force up to limiting friction limit f<sub>s(max)</sub>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q9: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The ratio of limiting friction f<sub>s(max)</sub> to normal reaction N is called:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Coefficient of kinetic friction</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Coefficient of static friction</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Angle of repose</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Rolling resistance</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">b) Coefficient of static friction</span></b><br>μ<sub>s</sub> = f<sub>s(max)</sub> / N.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q10: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The maximum safe speed for a car negotiating a flat level curve of radius r with static friction coefficient μ<sub>s</sub> is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) √(μ<sub>s</sub> g / r)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) √(μ<sub>s</sub> g r)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) μ<sub>s</sub> g r</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) r g / μ<sub>s</sub></div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">b) √(μ<sub>s</sub> g r)</span></b><br>v<sub>max</sub> = √(μ<sub>s</sub> g r).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q11: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">When a passenger jumps out of a moving train, he falls forward due to:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Inertia of rest</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Inertia of motion</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Inertia of direction</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Gravitational attraction</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">b) Inertia of motion</span></b><br>His feet touch the ground and stop, but his body continues moving forward due to inertia of motion.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q12: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The area under Force vs Time (F-t) graph represents:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Work done</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Power</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Impulse</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Acceleration</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">c) Impulse</span></b><br>Area under F-t graph = ∫ F dt = Impulse J.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q13: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Which friction force has the smallest magnitude among the following?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Static friction</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Limiting friction</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Kinetic friction</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Rolling friction</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">d) Rolling friction</span></b><br>Rolling friction (f<sub>r</sub>) is much smaller than sliding kinetic friction (f<sub>k</sub>) and limiting friction.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q14: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Angle of friction λ and coefficient of static friction μ<sub>s</sub> are related by:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) sin λ = μ<sub>s</sub></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) cos λ = μ<sub>s</sub></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) tan λ = μ<sub>s</sub></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) cot λ = μ<sub>s</sub></div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">c) tan λ = μ<sub>s</sub></span></b><br>tan λ = f<sub>s(max)</sub> / N = μ<sub>s</sub>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q15: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Angle of repose θ for an inclined plane is equal to:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Angle of friction λ</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 90° - λ</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) λ / 2</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 2 λ</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">a) Angle of friction λ</span></b><br>tan θ = μ<sub>s</sub> = tan λ, so Angle of Repose θ = Angle of Friction λ.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q16: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The optimum speed on a banked circular road of radius r with banking angle θ (without friction) is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) √(r g sin θ)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) √(r g cos θ)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) √(r g tan θ)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) r g tan θ</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">c) √(r g tan θ)</span></b><br>v<sub>0</sub> = √(r g tan θ).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q17: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A body of mass 2 kg moving at 10 m s<sup>-1</sup> is brought to rest in 2 s. The stopping force is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 5 N</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 10 N</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 20 N</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 40 N</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">b) 10 N</span></b><br>a = (0 - 10)/2 = -5 m/s<sup>2</sup>. F = m a = 2 × (-5) = -10 N (magnitude 10 N).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q18: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Working of rocket propulsion is based on:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Conservation of mass</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Conservation of energy</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Conservation of linear momentum</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Conservation of angular momentum</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">c) Conservation of linear momentum</span></b><br>Forward thrust on rocket is produced by conservation of linear momentum as gases are ejected backward.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q19: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">When a horse pulls a wagon, the force that causes the horse to move forward is exerted by:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) The wagon on the horse</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) The ground on the horse</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) The horse on the ground</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) The horse on the wagon</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">b) The ground on the horse</span></b><br>The horse pushes ground backward; the ground exerts an equal and opposite reaction force forward on horse feet.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q20: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">If three concurrent forces F<sub>1</sub>, F<sub>2</sub>, F<sub>3</sub> are in equilibrium, their vector sum is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) F<sub>1</sub> + F<sub>2</sub></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 0</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) F<sub>3</sub></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Infinite</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">b) 0</span></b><br>Equilibrium condition for concurrent forces: ∑ F = F<sub>1</sub> + F<sub>2</sub> + F<sub>3</sub> = 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q21: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A cyclist bends inward while taking a turn to:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Increase friction</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Provide necessary centripetal force</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Reduce speed</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Prevent air resistance</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">b) Provide necessary centripetal force</span></b><br>Bending inward allows horizontal component of normal reaction to provide centripetal force (tan θ = v<sup>2</sup>/(rg)).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q22: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Coefficient of kinetic friction μ<sub>k</sub> compared to static friction coefficient μ<sub>s</sub> is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) μ<sub>k</sub> > μ<sub>s</sub></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) μ<sub>k</sub> < μ<sub>s</sub></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) μ<sub>k</sub> = μ<sub>s</sub></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) μ<sub>k</sub> = 0</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">b) μ<sub>k</sub> < μ<sub>s</sub></span></b><br>Once sliding starts, microscopic cold welds break, so kinetic friction is slightly less than static friction (μ<sub>k</sub> < μ<sub>s</sub>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q23: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 1000 kg car moves around a turn of radius 50 m at 10 m s<sup>-1</sup>. Required centripetal force is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 1000 N</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 2000 N</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 5000 N</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 10000 N</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">b) 2000 N</span></b><br>F<sub>c</sub> = m v<sup>2</sup> / r = [1000 × 10<sup>2</sup>] / 50 = 100000 / 50 = 2000 N.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q24: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Lami's theorem is applicable for:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Two non-concurrent forces</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Three coplanar concurrent forces in equilibrium</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Four parallel forces</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Variable forces</div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">b) Three coplanar concurrent forces in equilibrium</span></b><br>Lami's theorem applies specifically to 3 coplanar concurrent forces in equilibrium: F<sub>1</sub>/sin α = F<sub>2</sub>/sin β = F<sub>3</sub>/sin γ.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q25: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A bomb of mass 9 kg at rest explodes into two pieces of 3 kg and 6 kg. If 3 kg piece moves at 16 m s<sup>-1</sup>, speed of 6 kg piece is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 4 m s<sup>-1</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 8 m s<sup>-1</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 12 m s<sup>-1</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 16 m s<sup>-1</sup></div>\n  </div></div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF8A65;\">b) 8 m s<sup>-1</sup></span></b><br>By momentum conservation: 0 = m<sub>1</sub> v<sub>1</sub> + m<sub>2</sub> v<sub>2</sub> ⇒ 3(16) + 6 v<sub>2</sub> = 0 ⇒ 48 + 6 v<sub>2</sub> = 0 ⇒ |v<sub>2</sub>| = 8 m s<sup>-1</sup>.\n    </div>\n  </div><h3 style=\"color: #FF8A65; border-left: 4px solid #FF8A65; padding-left: 10px; margin-top: 35px;\">Part B: Very Short Answer Questions (Q26 - Q55)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q26: Define Force</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define force according to Newton's First Law.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Force is an external agency in the form of a push or pull that changes or tends to change a body's state of rest or uniform motion.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q27: Define Inertia</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is inertia? State its quantitative measure.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Inertia is the natural resistance of a body to any change in its state of rest or uniform motion. Mass is the quantitative measure of inertia.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q28: Inertia of Rest Example</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Give one practical example of inertia of rest.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      When a carpet is beaten with a stick, dust particles fall off because the carpet moves with the stick while dust particles tend to remain at rest due to inertia of rest.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q29: Inertia of Motion Example</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Give one practical example of inertia of motion.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      An athlete runs some distance before taking a long jump to gain momentum and inertia of motion, which helps jump farther.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q30: Inertia of Direction Example</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Give one practical example of inertia of direction.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Mud flying off a rotating bicycle tire flies tangentially due to inertia of direction.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q31: Define Linear Momentum</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define linear momentum and state its SI unit.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Linear momentum is total quantity of motion contained in a body, defined as p = m v. SI unit: kg m s<sup>-1</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q32: Newton's Second Law Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State Newton's Second Law in mathematical vector form.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      F = dp / dt = d(m v) / dt = m a (for constant mass).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q33: Define Newton (N)</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define 1 Newton force in SI units.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      One Newton is the net force that produces an acceleration of 1 m s<sup>-2</sup> in a body of mass 1 kg (1 N = 1 kg m s<sup>-2</sup>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q34: Define Dyne</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define 1 Dyne force in CGS units.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      One Dyne is the net force that produces an acceleration of 1 cm s<sup>-2</sup> in a body of mass 1 g (1 dyne = 10<sup>-5</sup> N).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q35: Define Impulse</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define impulse of a force.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Impulse is the product of average force and time interval for which it acts: J = F<sub>avg</sub> × Δt = Δp.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q36: Impulse-Momentum Theorem Statement</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State Impulse-Momentum Theorem.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Impulse-Momentum Theorem states that impulse of a force equals total change in linear momentum produced: J = Δp.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q37: Newton's Third Law Statement</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State Newton's Third Law of Motion.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      To every action force, there is always an equal and opposite reaction force (F<sub>12</sub> = -F<sub>21</sub>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q38: Action and Reaction Simultaneous</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Do action and reaction forces act on the same body?</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      No, action and reaction forces act simultaneously on TWO DIFFERENT interacting bodies.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q39: Conservation of Linear Momentum Statement</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State Law of Conservation of Linear Momentum.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      In an isolated system with zero net external force (F<sub>ext</sub> = 0), total linear momentum remains strictly constant.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q40: Recoil Velocity Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Write recoil velocity formula for a gun of mass M firing bullet of mass m at velocity v.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      v<sub>recoil</sub> = - (m v) / M.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q41: Define Concurrent Forces</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What are concurrent forces?</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Concurrent forces are forces whose lines of action intersect at a single common point.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q42: Equilibrium Condition for Concurrent Forces</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the mathematical condition for equilibrium of 3 concurrent forces.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      ∑ F = F<sub>1</sub> + F<sub>2</sub> + F<sub>3</sub> = 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q43: State Lami's Theorem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State Lami's Theorem formula for 3 forces.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      F<sub>1</sub> / sin α = F<sub>2</sub> / sin β = F<sub>3</sub> / sin γ.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q44: Define Friction</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is friction force?</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Friction is the tangential contact force that opposes relative motion or tendency of relative motion between two surfaces.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q45: Define Static Friction</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define static friction.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Static friction is self-adjusting opposing force that prevents relative sliding between two contact surfaces up to limiting friction.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q46: Define Limiting Friction</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define limiting friction.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Limiting friction f<sub>s(max)</sub> is the maximum value of static friction just before relative sliding motion begins.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q47: Define Kinetic Friction</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define kinetic friction.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Kinetic friction f<sub>k</sub> is constant opposing contact force acting between surfaces in relative sliding motion.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q48: Define Rolling Friction</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is rolling friction?</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Rolling friction is the opposing force encountered when a spherical or cylindrical object rolls on a surface.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q49: State Coefficient of Static Friction Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State formula for coefficient of static friction μ<sub>s</sub>.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      μ<sub>s</sub> = f<sub>s(max)</sub> / N.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q50: Define Angle of Friction</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define angle of friction λ.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Angle of friction λ is the angle between resultant contact force S and normal reaction N when limiting friction acts: tan λ = μ<sub>s</sub>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q51: Define Angle of Repose</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define angle of repose θ.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Angle of repose is the minimum inclination of a rough plane at which a body just begins to slide down under gravity: tan θ = μ<sub>s</sub>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q52: Methods to Reduce Friction</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State two common methods to reduce friction.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1. Applying lubricants (oil, grease, graphite).<br>2. Using ball bearings to convert sliding friction into rolling friction.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q53: Centripetal Force Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State centripetal force formula for mass m in radius r with speed v.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      F<sub>c</sub> = m v<sup>2</sup> / r = m r ω<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q54: Max Speed on Level Road Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State formula for maximum safe speed of a vehicle on a level curve.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      v<sub>max</sub> = √(μ<sub>s</sub> g r).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q55: Optimum Banked Road Speed Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State formula for optimum speed on a banked road without friction.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      v<sub>0</sub> = √(r g tan θ).\n    </div>\n  </div><h3 style=\"color: #FF8A65; border-left: 4px solid #FF8A65; padding-left: 10px; margin-top: 35px;\">Part C: Short Answer Questions (Q56 - Q85)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q56: Galileo Inclined Plane Reasoning</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain how Galileo's experiments disproved Aristotelian view of motion.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Aristotle claimed force is needed to sustain uniform motion. Galileo showed a ball rolling down an incline gains speed, rolling up loses speed, so on a frictionless horizontal surface it moves indefinitely with constant velocity without net force!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q57: Derive F = ma from Newton's Second Law</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive F = m a from Newton's Second Law statement.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Statement: F ∝ dp/dt. Since p = mv, F = k d(mv)/dt.<br>For constant mass m, d(mv)/dt = m (dv/dt) = m a.<br>Setting k = 1 in SI units: <b>F = m a</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q58: Why Second Law is Real Law of Motion</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Prove why Newton's Second Law is called the real law of motion.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1. <b>First Law from Second Law:</b> If F = 0 in F = ma, then a = 0 ⇒ v = constant (body stays at rest/uniform motion).<br>2. <b>Third Law from Second Law:</b> Impulse F<sub>12</sub> Δt = Δp<sub>1</sub> and F<sub>21</sub> Δt = Δp<sub>2</sub>. In isolated system Δp<sub>1</sub> + Δp<sub>2</sub> = 0 ⇒ F<sub>12</sub> = -F<sub>21</sub>.<br>Thus, Second Law contains both First and Third Laws!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q59: Impulse Cricket Ball Application</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Why does a cricketer lower his hands while catching a ball?</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Impulse J = F × Δt = Δp. By pulling hands backward, time interval Δt for momentum to reach zero is increased, which significantly reduces retarding force F on hands, preventing hurt.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q60: Apparent Weight in a Lift Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Calculate apparent weight of a 60 kg man in an elevator (g = 10 m s<sup>-2</sup>) moving (i) upward at 2 m s<sup>-2</sup>, (ii) downward at 2 m s<sup>-2</sup>.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      (i) <b>Upward Acceleration:</b> N = m(g + a) = 60(10 + 2) = 60(12) = <b>720 N</b>.<br>(ii) <b>Downward Acceleration:</b> N = m(g - a) = 60(10 - 2) = 60(8) = <b>480 N</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q61: Recoil of Gun Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 5 kg rifle fires a 50 g bullet at speed 400 m s<sup>-1</sup>. Calculate recoil velocity of rifle.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Mass bullet m = 0.05 kg, velocity v = 400 m/s, mass gun M = 5 kg.<br>v<sub>recoil</sub> = -(m v)/M = -(0.05 × 400) / 5 = -20 / 5 = <b>-4 m s<sup>-1</sup></b> (backward).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q62: Prove Angle of Repose Equals Angle of Friction</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Prove that Angle of Repose θ equals Angle of Friction λ.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      On inclined plane at angle of repose θ, component mg sin θ balances limiting friction f<sub>s(max)</sub> and mg cos θ balances normal reaction N.<br>f<sub>s(max)</sub> = mg sin θ &nbsp;and&nbsp; N = mg cos θ.<br>μ<sub>s</sub> = f<sub>s(max)</sub> / N = (mg sin θ) / (mg cos θ) = tan θ.<br>Since tan λ = μ<sub>s</sub>, <b>tan θ = tan λ ⇒ θ = λ</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q63: Block on Rough Plane Acceleration</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A block of mass 4 kg slides down an inclined plane of angle 30° with μ<sub>k</sub> = 0.2. Calculate acceleration (g = 10 m s<sup>-2</sup>).</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Downward force along plane = mg sin 30° - f<sub>k</sub> = mg sin 30° - μ<sub>k</sub> mg cos 30°.<br>Acceleration a = g (sin 30° - μ<sub>k</sub> cos 30°) = 10 (0.5 - 0.2 × 0.866) = 10 (0.5 - 0.1732) = 10 × 0.3268 = <b>3.27 m s<sup>-2</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q64: Tension in Connected Motion Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Two masses m<sub>1</sub> = 3 kg and m<sub>2</sub> = 2 kg connected by string over frictionless pulley. Find acceleration and tension.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Acceleration a = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">(m<sub>1</sub> - m<sub>2</sub>) g</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">(3 - 2) 10</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">3 + 2</span>\n  </span> = 10 / 5 = <b>2 m s<sup>-2</sup></b>.<br>Tension T = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 m<sub>1</sub> m<sub>2</sub> g</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2(3)(2)(10)</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">5</span>\n  </span> = 120 / 5 = <b>24 N</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q65: Bending of Cyclist Derivation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive expression for angle of leaning θ of a cyclist taking a turn of radius r at speed v.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Inward torque about center of mass must balance outward torque.<br>Normal reaction N balances weight: N = mg.<br>Frictional force f provides centripetal force: f = m v<sup>2</sup> / r.<br>Leaning angle with vertical: tan θ = f / N = (m v<sup>2</sup> / r) / (mg) = <b>v<sup>2</sup> / (r g)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q66: Level Circular Road Skidding Limit Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A car takes a turn of radius 40 m on a level road with μ<sub>s</sub> = 0.4. Find max speed to avoid skidding (g = 9.8 m s<sup>-2</sup>).</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      v<sub>max</sub> = √(μ<sub>s</sub> g r) = √(0.4 × 9.8 × 40) = √156.8 = <b>12.52 m s<sup>-1</sup> (45.1 km/h)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q67: Banked Road Optimum Speed Calculation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A highway curve of radius 100 m is banked at 15°. Find optimum speed (tan 15° = 0.268, g = 9.8 m s<sup>-2</sup>).</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      v<sub>0</sub> = √(r g tan θ) = √(100 × 9.8 × 0.268) = √262.64 = <b>16.2 m s<sup>-1</sup> (58.3 km/h)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q68: Rocket Thrust Formula Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Gas is ejected from a rocket at rate 50 kg s<sup>-1</sup> with exhaust speed 2000 m s<sup>-1</sup>. Calculate thrust on rocket.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Thrust F = u<sub>ex</sub> (dm/dt) = 2000 × 50 = <b>100,000 N (100 kN)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q69: Lami's Theorem Numerical Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 10 kg mass suspended by two strings making angles 30° and 60° with horizontal. Find tensions T<sub>1</sub> and T<sub>2</sub> (g = 10 m s<sup>-2</sup>).</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      T<sub>1</sub> cos 30° = T<sub>2</sub> cos 60° &nbsp;and&nbsp; T<sub>1</sub> sin 30° + T<sub>2</sub> sin 60° = 100.<br>T<sub>1</sub> (√3/2) = T<sub>2</sub> (1/2) ⇒ T<sub>2</sub> = √3 T<sub>1</sub>.<br>Substitute: T<sub>1</sub> (1/2) + (√3 T<sub>1</sub>) (√3/2) = 100 ⇒ T<sub>1</sub> (1/2 + 3/2) = 100 ⇒ 2 T<sub>1</sub> = 100.<br><b>T<sub>1</sub> = 50 N</b> &nbsp;and&nbsp; <b>T<sub>2</sub> = 50√3 ≈ 86.6 N</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q70: Static vs Kinetic Friction Differences</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Differentiate between static friction and kinetic friction with 4 comparison points.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1. <b>Occurrence:</b> Static friction acts before sliding; Kinetic acts during sliding.<br>2. <b>Self-adjustment:</b> Static is self-adjusting (0 to f<sub>s(max)</sub>); Kinetic is constant.<br>3. <b>Coefficient:</b> μ<sub>s</sub> is larger than μ<sub>k</sub>.<br>4. <b>Formula:</b> f<sub>s(max)</sub> = μ<sub>s</sub> N; f<sub>k</sub> = μ<sub>k</sub> N.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q71: Why Rolling Friction is Smaller than Sliding Friction</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain micro-mechanism why rolling friction is much smaller than sliding friction.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Sliding involves continuous breaking of microscopic cold welds across entire contact area. Rolling involves surface indentation and momentary line contact without relative sliding, reducing resistance enormously.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q72: Horse Cart Paradox Explained</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain the paradox: 'Horse pulls cart with force F, cart pulls horse with -F; how does system move?'</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Action and reaction forces act on different bodies. Horse pushes ground backward with force F<sub>H</sub>; ground pushes horse forward with reaction R<sub>H</sub>. If R<sub>H</sub> > backward pull of cart, horse moves forward!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q73: Impulse Calculation from F-t Data</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A force F = (20 t + 5) N acts on a 2 kg mass for 2 s. Calculate impulse and final velocity from rest.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Impulse J = ∫<sub>0</sub><sup>2</sup> (20 t + 5) dt = [10 t<sup>2</sup> + 5 t]<sub>0</sub><sup>2</sup> = 10(4) + 5(2) = 40 + 10 = <b>50 N s</b>.<br>Velocity: J = m Δv ⇒ 50 = 2(v - 0) ⇒ <b>v = 25 m s<sup>-1</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q74: Block Pulled at Angle on Rough Floor</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 10 kg block is pulled by 50 N force at 37° to horizontal on floor with μ<sub>k</sub> = 0.2. Find acceleration (cos 37°=0.8, sin 37°=0.6).</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      F<sub>x</sub> = 50 cos 37° = 40 N, F<sub>y</sub> = 50 sin 37° = 30 N.<br>Normal reaction N = mg - F<sub>y</sub> = 100 - 30 = 70 N.<br>Friction f<sub>k</sub> = μ<sub>k</sub> N = 0.2 × 70 = 14 N.<br>Net force F<sub>net</sub> = 40 - 14 = 26 N.<br>Acceleration a = F<sub>net</sub> / m = 26 / 10 = <b>2.6 m s<sup>-2</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q75: Momentum Conservation Bomb Explosion Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A shell of mass 5 kg moving at 20 m s<sup>-1</sup> explodes into two fragments of 2 kg and 3 kg. If 2 kg fragment moves at 50 m s<sup>-1</sup> in same direction, find speed of 3 kg fragment.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Total initial momentum = 5 × 20 = 100 kg m s<sup>-1</sup>.<br>Final momentum = 2(50) + 3 v<sub>2</sub> = 100 + 3 v<sub>2</sub>.<br>By conservation: 100 = 100 + 3 v<sub>2</sub> ⇒ 3 v<sub>2</sub> = 0 ⇒ <b>v<sub>2</sub> = 0 m s<sup>-1</sup></b> (3 kg fragment comes to rest).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q76: Limiting Friction Problem on Flat Floor</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 20 kg crate rests on floor with μ<sub>s</sub> = 0.5. Calculate horizontal force needed to just start moving it (g = 9.8 m s<sup>-2</sup>).</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Limiting friction f<sub>s(max)</sub> = μ<sub>s</sub> N = μ<sub>s</sub> m g = 0.5 × 20 × 9.8 = <b>98 Newtons</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q77: Why Banking of Roads is Necessary</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Why is banking of roads preferred over relying on tire friction for circular turns?</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Tire friction μ<sub>s</sub> fluctuates with rain, ice, or tire wear, leading to skidding risks. Banking utilizes normal reaction component N sin θ to guarantee centripetal force independent of friction!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q78: Explain Inertial vs Non-Inertial Frame Pseudo Force</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is a pseudo force? Give an example.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A pseudo force F<sub>pseudo</sub> = -m a<sub>frame</sub> is an apparent fictitious force observed in an accelerating non-inertial frame to make Newton's second law valid (e.g. centrifugal force in rotating frame).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q79: Momentum Vector Component Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Momentum of a particle p = 3 cos(2t) î + 3 sin(2t) ĵ kg m s<sup>-1</sup>. Find force vector F and magnitude |F|.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      F = dp/dt = d/dt [3 cos(2t) î + 3 sin(2t) ĵ] = <b>-6 sin(2t) î + 6 cos(2t) ĵ</b>.<br>Magnitude |F| = √[(-6 sin 2t)<sup>2</sup> + (6 cos 2t)<sup>2</sup>] = √(36 sin<sup>2</sup> 2t + 36 cos<sup>2</sup> 2t) = <b>6 Newtons</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q80: Incline Angle of Repose Sliding Condition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">If an incline has angle 45° and μ<sub>s</sub> = 0.5, show that a block will slide down.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Angle of repose θ<sub>r</sub> = tan<sup>-1</sup>(μ<sub>s</sub>) = tan<sup>-1</sup>(0.5) ≈ 26.6°.<br>Since incline angle 45° > 26.6°, mg sin 45° > f<sub>s(max)</sub>, so block will definitely slide!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q81: Variable Force Impulse Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A force F(t) = 6 t<sup>2</sup> N acts on 1 kg mass for t = 0 to t = 3 s. Calculate change in velocity.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Impulse J = ∫<sub>0</sub><sup>3</sup> 6 t<sup>2</sup> dt = [2 t<sup>3</sup>]<sub>0</sub><sup>3</sup> = 2(27) = 54 N s.<br>Δv = J / m = 54 / 1 = <b>54 m s<sup>-1</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q82: Three Blocks Connected by Strings Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Three blocks of 1 kg, 2 kg, 3 kg tied in series pulled by 12 N force on smooth table. Find acceleration and string tensions.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Total mass = 1 + 2 + 3 = 6 kg. Acceleration a = 12 / 6 = <b>2 m s<sup>-2</sup></b>.<br>Tension T<sub>1</sub> (behind 1 kg) = 1 × 2 = <b>2 N</b>.<br>Tension T<sub>2</sub> (behind 1+2 kg) = (1 + 2) × 2 = <b>6 N</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q83: Overcoming Friction Work Concept</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Calculate work done in dragging a 10 kg block by 5 m on rough floor with μ<sub>k</sub> = 0.3 (g = 10 m s<sup>-2</sup>).</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Frictional force f<sub>k</sub> = μ<sub>k</sub> m g = 0.3 × 10 × 10 = 30 N.<br>Work W = f<sub>k</sub> × d = 30 × 5 = <b>150 Joules</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q84: Centripetal Acceleration on Curved Path</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A car of 1200 kg negotiates a curve of 100 m at 20 m s<sup>-1</sup>. Find centripetal acceleration and force.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      a<sub>c</sub> = v<sup>2</sup> / r = 400 / 100 = <b>4 m s<sup>-2</sup></b>.<br>Force F<sub>c</sub> = m a<sub>c</sub> = 1200 × 4 = <b>4800 Newtons</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q85: Weightlessness in Free Fall</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Why does a body experience weightlessness during free fall?</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      During free fall, downward acceleration of body equals g. Normal reaction from supporting floor N = m(g - g) = 0, so apparent weight becomes zero!\n    </div>\n  </div><h3 style=\"color: #FF8A65; border-left: 4px solid #FF8A65; padding-left: 10px; margin-top: 35px;\">Part D: Long Answer Questions (Q86 - Q100)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q86: Derivation of Newton's Laws & F = ma Master Theory</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State Newton's three laws of motion. Derive F = ma from the Second Law and prove that Newton's Second Law is the real law containing the first and third laws.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Newton's Three Laws:</b><br>1. <b>First Law:</b> A body remains at rest or in uniform straight-line motion unless acted upon by net external force.<br>2. <b>Second Law:</b> Rate of change of linear momentum is directly proportional to applied force (F = dp/dt).<br>3. <b>Third Law:</b> To every action force, there is an equal and opposite reaction force (F<sub>12</sub> = -F<sub>21</sub>).<br><br><b>Derivation of F = ma:</b><br>F = k dp/dt = k d(mv)/dt. For constant mass m and setting k = 1 in SI: <b>F = m a</b>.<br><br><b>Proof Second Law Contains First Law:</b><br>If F = 0 in F = ma, then a = 0 ⇒ v = constant (rest or uniform motion maintained).<br><br><b>Proof Second Law Contains Third Law:</b><br>In isolated system of two bodies A and B (F<sub>ext</sub> = 0):<br>dp<sub>A</sub>/dt + dp<sub>B</sub>/dt = 0 ⇒ F<sub>BA</sub> + F<sub>AB</sub> = 0 ⇒ <b>F<sub>AB</sub> = -F<sub>BA</sub></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q87: Conservation of Linear Momentum Derivation & Applications</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State and prove the Law of Conservation of Linear Momentum using Newton's Second and Third Laws. Explain recoil of gun and rocket propulsion.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Statement:</b> In an isolated system (F<sub>ext</sub> = 0), total linear momentum is conserved.<br><br><b>Proof using Newton's Laws:</b><br>Consider collision between bodies A and B.<br>Force on A by B: F<sub>AB</sub> = dp<sub>A</sub>/dt.<br>Force on B by A: F<sub>BA</sub> = dp<sub>B</sub>/dt.<br>By Third Law: F<sub>AB</sub> = -F<sub>BA</sub> ⇒ dp<sub>A</sub>/dt + dp<sub>B</sub>/dt = 0 ⇒ d(p<sub>A</sub> + p<sub>B</sub>)/dt = 0.<br>Integrating: <b>p<sub>A</sub> + p<sub>B</sub> = Constant</b>.<br><br><b>Recoil of Gun:</b> Initial momentum = 0. Bullet momentum p<sub>b</sub> = mv, gun recoil momentum p<sub>g</sub> = MV<sub>r</sub>.<br>mv + MV<sub>r</sub> = 0 ⇒ <b>V<sub>r</sub> = -(m v)/M</b>.<br><br><b>Rocket Propulsion:</b> Ejection of burnt gases backward at speed u<sub>ex</sub> produces forward reaction force (thrust) F = u<sub>ex</sub> (dm/dt).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q88: Complete Theory of Friction & Angle of Repose Derivation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define Static, Limiting, Kinetic, and Rolling friction. State the laws of limiting friction and derive Angle of Repose = Angle of Friction.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Types of Friction:</b><br>1. Static friction f<sub>s</sub> (self-adjusting force preventing motion).<br>2. Limiting friction f<sub>s(max)</sub> (maximum static friction before sliding).<br>3. Kinetic friction f<sub>k</sub> (friction during sliding motion).<br>4. Rolling friction f<sub>r</sub> (resistance during rolling).<br><br><b>Laws of Limiting Friction:</b><br>- f<sub>s(max)</sub> ∝ Normal reaction N.<br>- Depends on nature and roughness of contact surfaces.<br>- Independent of area of contact for given normal reaction.<br><br><b>Derivation (Angle of Repose = Angle of Friction):</b><br>On incline at angle θ<sub>r</sub>: f<sub>s(max)</sub> = mg sin θ<sub>r</sub> &nbsp;and&nbsp; N = mg cos θ<sub>r</sub>.<br>μ<sub>s</sub> = f<sub>s(max)</sub> / N = tan θ<sub>r</sub>.<br>Since angle of friction tan λ = μ<sub>s</sub>, <b>tan θ<sub>r</sub> = tan λ ⇒ θ<sub>r</sub> = λ</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q89: Complete Dynamics of Banked Circular Road</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive the formula for maximum safe speed v<sub>max</sub> of a vehicle on a banked circular road with coefficient of static friction μ<sub>s</sub>.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Consider a car of mass m on a road banked at angle θ with radius r.<br>Forces acting: Weight mg downward, Normal reaction N perpendicular to bank, Friction f<sub>s</sub> down the incline.<br><br><b>Vertical Equilibrium:</b><br>N cos θ - f<sub>s</sub> sin θ = mg &nbsp; ⇒ &nbsp; mg = N cos θ - μ<sub>s</sub> N sin θ = N (cos θ - μ<sub>s</sub> sin θ).<br><br><b>Centripetal Force (Horizontal Balance):</b><br>N sin θ + f<sub>s</sub> cos θ = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m v<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r</span>\n  </span> &nbsp; ⇒ &nbsp; <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m v<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r</span>\n  </span> = N (sin θ + μ<sub>s</sub> cos θ).<br><br><b>Divide Centripetal Equation by Vertical Equation:</b><br><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r g</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">N (sin θ + μ<sub>s</sub> cos θ)</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">N (cos θ - μ<sub>s</sub> sin θ)</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">tan θ + μ<sub>s</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">1 - μ<sub>s</sub> tan θ</span>\n  </span>.<br><br><b>Maximum Safe Speed v<sub>max</sub>:</b><br><b>v<sub>max</sub> = √[ r g <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">μ<sub>s</sub> + tan θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">1 - μ<sub>s</sub> tan θ</span>\n  </span> ]</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q90: Atwood Machine Connected Motion Derivation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive expressions for acceleration a and string tension T for two masses m<sub>1</sub> and m<sub>2</sub> (m<sub>1</sub> > m<sub>2</sub>) connected over a light frictionless pulley.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Let m<sub>1</sub> move downward with acceleration a and m<sub>2</sub> move upward with acceleration a.<br><br><b>Equation for Mass 1 (Downward):</b><br>m<sub>1</sub> g - T = m<sub>1</sub> a &nbsp; ---(Equation 1)<br><br><b>Equation for Mass 2 (Upward):</b><br>T - m<sub>2</sub> g = m<sub>2</sub> a &nbsp; ---(Equation 2)<br><br><b>Adding Equations 1 and 2:</b><br>(m<sub>1</sub> - m<sub>2</sub>) g = (m<sub>1</sub> + m<sub>2</sub>) a &nbsp; ⇒ &nbsp; <b>a = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">(m<sub>1</sub> - m<sub>2</sub>) g</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span></b>.<br><br><b>Substitute a into Equation 2 for Tension T:</b><br>T = m<sub>2</sub> g + m<sub>2</sub> [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">(m<sub>1</sub> - m<sub>2</sub>) g</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span> ] = <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 m<sub>1</sub> m<sub>2</sub> g</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q91: Lami's Theorem Statement & Vector Proof</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State Lami's theorem and prove it analytically using vector cross product for three concurrent coplanar forces F<sub>1</sub>, F<sub>2</sub>, F<sub>3</sub> in equilibrium.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Lami's Theorem:</b> For 3 coplanar concurrent forces in equilibrium, F<sub>1</sub>/sin α = F<sub>2</sub>/sin β = F<sub>3</sub>/sin γ.<br><br><b>Proof:</b><br>F<sub>1</sub> + F<sub>2</sub> + F<sub>3</sub> = 0 ⇒ F<sub>1</sub> + F<sub>2</sub> = -F<sub>3</sub>.<br>Take cross product with F<sub>1</sub>:<br>F<sub>1</sub> × (F<sub>1</sub> + F<sub>2</sub> + F<sub>3</sub>) = 0 ⇒ 0 + F<sub>1</sub> × F<sub>2</sub> + F<sub>1</sub> × F<sub>3</sub> = 0 ⇒ <b>F<sub>1</sub> × F<sub>2</sub> = F<sub>3</sub> × F<sub>1</sub></b>.<br>Similarly, cross product with F<sub>2</sub> yields: <b>F<sub>1</sub> × F<sub>2</sub> = F<sub>2</sub> × F<sub>3</sub></b>.<br>Thus |F<sub>1</sub> × F<sub>2</sub>| = |F<sub>2</sub> × F<sub>3</sub>| = |F<sub>3</sub> × F<sub>1</sub>|.<br>F<sub>1</sub> F<sub>2</sub> sin(180° - γ) = F<sub>2</sub> F<sub>3</sub> sin(180° - α) = F<sub>3</sub> F<sub>1</sub> sin(180° - β).<br>F<sub>1</sub> F<sub>2</sub> sin γ = F<sub>2</sub> F<sub>3</sub> sin α = F<sub>3</sub> F<sub>1</sub> sin β.<br>Dividing throughout by F<sub>1</sub> F<sub>2</sub> F<sub>3</sub>:<br><b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">F<sub>1</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">sin α</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">F<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">sin β</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">F<sub>3</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">sin γ</span>\n  </span></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q92: Block Pulled vs Pushed on Rough Floor</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Prove mathematically why it is easier to pull a lawn roller than to push it on a rough horizontal floor.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Let P be force applied at angle θ with horizontal.<br><br><b>Case 1: Pushing:</b><br>Vertical force component acts DOWNWARD.<br>Normal reaction N<sub>push</sub> = mg + P sin θ.<br>Friction force f<sub>push</sub> = μ<sub>k</sub> N<sub>push</sub> = <b>μ<sub>k</sub> (mg + P sin θ)</b>.<br><br><b>Case 2: Pulling:</b><br>Vertical force component acts UPWARD.<br>Normal reaction N<sub>pull</sub> = mg - P sin θ.<br>Friction force f<sub>pull</sub> = μ<sub>k</sub> N<sub>pull</sub> = <b>μ<sub>k</sub> (mg - P sin θ)</b>.<br><br><b>Conclusion:</b> Since N<sub>pull</sub> < N<sub>push</sub>, f<sub>pull</sub> < f<sub>push</sub>. Therefore, pulling requires significantly less force than pushing!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q93: Rocket Propulsion Calculus Derivation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive the rocket velocity formula v(t) = v<sub>0</sub> + u<sub>ex</sub> ln(m<sub>0</sub>/m) and upward thrust expression.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Consider rocket of mass m moving at velocity v. In time dt, mass dm of gas is ejected at velocity u<sub>ex</sub> backward.<br>Momentum conservation:<br>m v = (m - dm)(v + dv) + dm (v - u<sub>ex</sub>).<br>m v = m v + m dv - v dm - dm dv + v dm - u<sub>ex</sub> dm.<br>Ignoring small dm dv term: m dv = u<sub>ex</sub> dm.<br>dv = -u<sub>ex</sub> (dm / m).<br>Integrating from t=0 (m<sub>0</sub>, v<sub>0</sub>) to t (m, v):<br>∫<sub>v0</sub><sup>v</sup> dv = -u<sub>ex</sub> ∫<sub>m0</sub><sup>m</sup> (dm / m).<br>v - v<sub>0</sub> = -u<sub>ex</sub> [ln m]<sub>m0</sub><sup>m</sup> = u<sub>ex</sub> ln(m<sub>0</sub> / m).<br><b>v(t) = v<sub>0</sub> + u<sub>ex</sub> ln ( <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m<sub>0</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m</span>\n  </span> )</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q94: Master Block and Incline Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 10 kg block placed on an incline of 37° (μ<sub>s</sub> = 0.4, μ<sub>k</sub> = 0.3). (i) Will the block slide? (ii) Find friction force. (iii) Find acceleration if pulled UP the incline by 100 N force.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Given sin 37° = 0.6, cos 37° = 0.8, g = 10 m s<sup>-2</sup>.<br>Gravity component down plane = mg sin 37° = 100 × 0.6 = 60 N.<br>Normal N = mg cos 37° = 100 × 0.8 = 80 N.<br>Max static friction f<sub>s(max)</sub> = μ<sub>s</sub> N = 0.4 × 80 = 32 N.<br><br><b>(i) Will it slide under gravity alone?</b> Yes, 60 N > 32 N.<br><b>(ii) Friction force when sliding down:</b> Kinetic friction f<sub>k</sub> = μ<sub>k</sub> N = 0.3 × 80 = <b>24 N</b>.<br><b>(iii) Pulled UP by 100 N force:</b><br>Upward force = 100 N. Downward forces = mg sin 37° + f<sub>k</sub> = 60 + 24 = 84 N.<br>Net force F<sub>net</sub> = 100 - 84 = 16 N.<br>Acceleration a = F<sub>net</sub> / m = 16 / 10 = <b>1.6 m s<sup>-2</sup> UP the incline</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q95: Conical Pendulum Motion Derivation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive time period T of a conical pendulum of length L making angle θ with vertical.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Consider bob of mass m rotating in horizontal circle of radius r = L sin θ.<br>Vertical balance: T<sub>str</sub> cos θ = mg.<br>Horizontal balance (Centripetal force): T<sub>str</sub> sin θ = m v<sup>2</sup> / r = m r ω<sup>2</sup>.<br>Dividing equations: tan θ = (r ω<sup>2</sup>) / g = (L sin θ ω<sup>2</sup>) / g ⇒ ω<sup>2</sup> = g / (L cos θ).<br>Angular speed ω = √[ g / (L cos θ) ].<br>Time Period T = 2π / ω = <b>2 π √[ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L cos θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span> ]</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q96: Chain Sliding Off Rough Table Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A chain of length L and mass M lies on a rough table with coefficient of static friction μ<sub>s</sub>. Find max fraction of length that can hang over the edge without sliding.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Let fraction hanging over edge be x.<br>Hanging length = x L, Hanging mass = x M.<br>Table length = (1 - x) L, Table mass = (1 - x) M.<br>Downward pull of hanging part = (x M) g.<br>Limiting friction on table part = μ<sub>s</sub> N = μ<sub>s</sub> (1 - x) M g.<br>At sliding boundary: x M g = μ<sub>s</sub> (1 - x) M g ⇒ x = μ<sub>s</sub> - μ<sub>s</sub> x ⇒ x (1 + μ<sub>s</sub>) = μ<sub>s</sub>.<br><b>Hanging Fraction x = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">μ<sub>s</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">1 + μ<sub>s</sub></span>\n  </span></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q97: Motion of Two Blocks Stacked on Each Other</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 2 kg block A sits on a 4 kg block B on a smooth floor. μ<sub>s</sub> between A and B is 0.3. Find max horizontal force F on B so that both blocks move together.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      For both blocks to move together as a single 6 kg unit with max acceleration a<sub>max</sub>:<br>Max friction force on top block A: f<sub>s(max)</sub> = μ<sub>s</sub> m<sub>A</sub> g = 0.3 × 2 × 10 = 6 N.<br>Max acceleration of block A: a<sub>max</sub> = f<sub>s(max)</sub> / m<sub>A</sub> = 6 / 2 = 3 m s<sup>-2</sup>.<br>Force F applied on bottom block B to accelerate combined system at 3 m s<sup>-2</sup>:<br>F<sub>max</sub> = (m<sub>A</sub> + m<sub>B</sub>) a<sub>max</sub> = (2 + 4) × 3 = 6 × 3 = <b>18 Newtons</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q98: Dynamics of Motion in a Vertical Circle</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive minimum speed at lowest point and highest point for a body tied to a string of length L to complete a vertical circle.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      At highest point H: T<sub>H</sub> + mg = m v<sub>H</sub><sup>2</sup> / L.<br>For critical loop-the-loop, T<sub>H</sub> ≥ 0 ⇒ v<sub>H, min</sub> = <b>√(g L)</b>.<br><br>By Energy Conservation between lowest point L and highest point H:<br>1/2 m v<sub>L</sub><sup>2</sup> = 1/2 m v<sub>H</sub><sup>2</sup> + m g (2 L).<br>v<sub>L</sub><sup>2</sup> = v<sub>H</sub><sup>2</sup> + 4 g L = g L + 4 g L = 5 g L.<br>Minimum speed at lowest point: <b>v<sub>L, min</sub> = √(5 g L)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q99: Impulse and Collision Impact Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 0.15 kg baseball traveling at 40 m s<sup>-1</sup> is struck by a bat and flies back at 50 m s<sup>-1</sup> in opposite direction. If contact duration is 0.005 s, calculate average force exerted.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Initial velocity u = +40 m/s, final velocity v = -50 m/s.<br>Change in momentum Δp = m(v - u) = 0.15 (-50 - 40) = 0.15 (-90) = -13.5 kg m s<sup>-1</sup>.<br>Impulse J = -13.5 N s.<br>Average Force F<sub>avg</sub> = J / Δt = -13.5 / 0.005 = <b>-2700 Newtons</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF8A65; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q100: Master Variable Mass Rocket Dynamics Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A rocket of initial mass 1000 kg ejects gas at 10 kg s<sup>-1</sup> with exhaust speed 1500 m s<sup>-1</sup>. Calculate (i) initial thrust, (ii) velocity after 50 s if starting from rest.</div>\n    <div style=\"background: rgba(255, 138, 101, 0.05); border-left: 3.5px solid #FF8A65; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF8A65; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      (i) <b>Initial Thrust F:</b> F = u<sub>ex</sub> (dm/dt) = 1500 × 10 = <b>15,000 N (15 kN)</b>.<br>(ii) <b>Velocity at t = 50 s:</b><br>Mass burnt in 50 s = 10 × 50 = 500 kg.<br>Remaining mass m(50) = 1000 - 500 = 500 kg.<br>v(50) = u<sub>ex</sub> ln(m<sub>0</sub> / m) = 1500 ln(1000 / 500) = 1500 ln(2) = 1500 × 0.693 = <b>1039.5 m s<sup>-1</sup></b>.\n    </div>\n  </div></div>";




